fn tool_defs() -> Value {
    json!([
        {
            "name": "c3_providers",
            "description": "List the configured C3 reviewer providers (Codex model endpoints) and whether each is usable right now â€” the same table the `c3 providers` CLI prints. Use it before a consultation to sanity-check who is available, or with `short: true` for a one-line summary of what is OUT and how many reviewers are ready. Read-only; writes nothing.",
